// Removes footers that tools append to pull request descriptions ("Generated by [Tool](url)",
// session links), so descriptions hold only what the maintainer wrote. Run by the PR
// description workflow: for one pull request (PR_NUMBER), or for every pull request.
import process from 'node:process';
import { pathToFileURL } from 'node:url';

/** Footer lines a tool adds: a "Generated by/with [name](url)" credit, a session link, a rule above them. */
const FOOTER_LINE = /^(?:-{3,}|\W{0,4}_?Generated (?:by|with) \[[^\]\n]{1,80}\]\([^)\s]{1,300}\)_?\.?|https?:\/\/\S{1,200}\/session_[\w-]{1,100})\s*$/i;

/** `body` without the tool footer at its end. Returns `body` unchanged when it has none. */
export function cleanBody(body) {
  const lines = body.split('\n');
  let end = lines.length;
  while (end > 0 && (lines[end - 1].trim() === '' || FOOTER_LINE.test(lines[end - 1].trim()))) end -= 1;
  const removed = lines.slice(end);
  // Only a footer that credits a tool is removed: a trailing rule or blank lines alone are kept.
  if (!removed.some((line) => /Generated (?:by|with) \[|\/session_/i.test(line))) return body;
  return lines.slice(0, end).join('\n').trimEnd();
}

async function github(path, init = {}) {
  const response = await fetch(`https://api.github.com/repos/${process.env.REPO}${path}`, {
    ...init,
    headers: { authorization: `Bearer ${process.env.GH_TOKEN}`, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28', ...init.headers },
  });
  if (!response.ok) throw new Error(`${init.method ?? 'GET'} ${path}: HTTP ${String(response.status)}`);
  return response.json();
}

async function clean(number) {
  const pull = await github(`/pulls/${String(number)}`);
  const body = pull.body ?? '';
  const cleaned = cleanBody(body);
  if (cleaned === body) return false;
  await github(`/pulls/${String(number)}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ body: cleaned }) });
  console.log(`#${String(number)}: footer removed.`);
  return true;
}

async function main() {
  if (process.env.PR_NUMBER) {
    await clean(Number(process.env.PR_NUMBER));
    return;
  }
  let changed = 0;
  for (let page = 1; ; page += 1) {
    const pulls = await github(`/pulls?state=all&per_page=100&page=${String(page)}`);
    for (const pull of pulls) if (await clean(pull.number)) changed += 1;
    if (pulls.length < 100) break;
  }
  console.log(`${String(changed)} pull request description(s) cleaned.`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
